1.1.a.sql:
SELECT DISTINCT Nombre
FROM CLIENTES
WHERE Ciudad = 'Buenos Aires';

1.1.b.sql:
SELECT DISTINCT "Cod Producto", "Descripción"
FROM PRODUCTO
WHERE "Cod Producto" = "Descripción";

4.1.10.sql:
SELECT DISTINCT codigo_pedido, codigo_cliente, fecha_esperada, fecha_entrega
FROM pedido
WHERE fecha_entrega <= fecha_esperada - INTERVAL '2' DAY;

4.1.11.sql:
SELECT *
FROM pedido
WHERE EXTRACT(MONTH FROM fecha_entrega) = 1;

4.1.2.sql:
SELECT DISTINCT ciudad, telefono
FROM oficina
WHERE pais = 'España';

4.1.29.sql:
SELECT pais, COUNT(codigo_cliente) AS cantidad_clientes
FROM cliente
GROUP BY pais;

4.1.34.sql:
SELECT COUNT(*)
FROM cliente
WHERE ciudad = 'Madrid';

4.1.37.sql:
SELECT COUNT(*)
FROM cliente
WHERE codigo_empleado_rep_ventas IS NULL;

4.1.4.sql:
SELECT DISTINCT puesto, nombre, apellido1, apellido2, email
FROM empleado
WHERE codigo_jefe IS NULL;

4.1.40.sql:
SELECT codigo_pedido, SUM(cantidad)
FROM detalle_pedido
GROUP BY codigo_pedido;

4.1.46.sql:
SELECT EXTRACT(YEAR FROM fecha_pago) AS anio, SUM(total) AS suma_total
FROM pago
GROUP BY EXTRACT(YEAR FROM fecha_pago);

4.1.47.sql:
SELECT DISTINCT c.nombre_cliente
FROM cliente AS c
WHERE c.limite_credito = (
    SELECT MAX(limite_credito)
    FROM cliente
);

4.1.5.sql:
SELECT DISTINCT nombre, apellido1, apellido2, puesto
FROM empleado
WHERE puesto <> 'Representante Ventas';

4.1.55.sql:
SELECT DISTINCT p.nombre
FROM producto AS p
WHERE p.precio_venta = (
  SELECT MAX(p2.precio_venta)
  FROM producto AS p2
);

4.1.59.sql:
SELECT DISTINCT c.codigo_cliente, c.nombre_cliente, c.nombre_contacto, c.apellido_contacto, c.telefono, c.fax, c.linea_direccion1, c.linea_direccion2, c.ciudad, c.region, c.pais, c.codigo_postal, c.codigo_empleado_rep_ventas, c.limite_credito
FROM cliente AS c
INNER JOIN pago AS p ON c.codigo_cliente = p.codigo_cliente;

4.1.6.sql:
SELECT DISTINCT nombre_cliente
FROM cliente
WHERE pais = 'España';

4.1.65.sql:
SELECT DISTINCT c.*
FROM cliente AS c
INNER JOIN pago AS p ON c.codigo_cliente = p.codigo_cliente;

4.1.9.sql:
SELECT DISTINCT codigo_pedido, codigo_cliente, fecha_esperada, fecha_entrega
FROM pedido
WHERE fecha_entrega > fecha_esperada;

Extra.1.a.sql:
SELECT DISTINCT pelicula
FROM GUSTA
WHERE aficionado = 'José Perez';
